def _get_needed_agent_based_modules(check_plugin_names: Set[CheckPluginName], inventory_plugin_names: Set[str]) -> List[str]:
    check_plugins_opt: List[Optional[CheckPlugin]] = [agent_based_register.get_check_plugin(p) for p in check_plugin_names]
    modules = {plugin.module for plugin in check_plugins_opt if plugin is not None and plugin.module is not None}
    modules.update((section.module for section in agent_based_register.get_relevant_raw_sections(check_plugin_names=check_plugin_names).values() if section.module is not None))
    section_plugins_opt = (agent_based_register.get_section_plugin(SectionName(name.split('.')[0])) for name in inventory_plugin_names)
    modules.update((section.module for section in section_plugins_opt if section is not None and section.module is not None))
    return sorted(modules)

