def get_table_resize(table_data, table_col_count) -> bool:
    resize = False
    try:
        resize = table_data['fitToPageWidth']
    except:
        first_row = None
        try:
            first_row = table_data['rows'][0]
        except (KeyError, IndexError, TypeError):
            first_row = None
        if first_row and isinstance(first_row, list):
            total_width = 0
            for cell_data in first_row:
                content = cell_data.get('content', '') if isinstance(cell_data, dict) else ''
                font_size = cell_data.get('font_size', 12) if isinstance(cell_data, dict) else 12
                try:
                    est_width = len(content) * float(font_size) / 2
                except (TypeError, ValueError):
                    est_width = len(content) * 12 / 2
                total_width += est_width
            if total_width >= resizing_px_threshold:
                resize = True
        elif table_col_count >= resizing_col_threshold:
            resize = True
    return resize

def process_query(self, query: Query, request_settings: RequestSettings) -> None:

    def process_column(exp: Expression) -> Expression:
        if isinstance(exp, Column):
            if exp.column_name == 'group_id':
                return FunctionCall(exp.alias, 'nullIf', (Column(None, exp.table_name, exp.column_name), Literal(None, 0)))
            elif exp.column_name == 'message':
                return Column(None, exp.table_name, 'search_message')
        return exp
    query.transform_expressions(process_column)

def logMsg(self, msg, importance=5, msgType='status', exception=(None, None, None), **kwargs):
    try:
        currentDir = self.manager.getCurrentDir()
    except:
        currentDir = None
    if isinstance(currentDir, DirHandle):
        kwargs['currentDir'] = currentDir.name()
    now = str(time.strftime('%Y.%m.%d %H:%M:%S'))
    unique_suffix = str(int(time.time() * 1000000))
    name = 'LogEntry_' + unique_suffix
    entry = {'docs': None, 'reasons': None, 'message': msg, 'timestamp': now, 'importance': importance, 'msgType': msgType, 'exception': exception}
    for k in kwargs:
        entry[k] = kwargs[k]
    self.processEntry(entry)
    self.saveEntry({name: entry})
    self.displayEntry(entry)

def get_working_copy_status_json(repo, list_untracked_tables):
    if repo.is_bare:
        return None
    result = {'parts': repo.working_copy.parts_status(), 'changes': get_diff_status_json(repo), 'nonCheckoutDatasets': sorted(repo.non_checkout_datasets)}
    if list_untracked_tables:
        result['untrackedTables'] = get_untracked_tables(repo)
    return result

def compute_hint_frame_locations(self, operations):
    op = operations[-1]
    if op.getopnum() != rop.JUMP:
        return
    self.final_jump_op = op
    descr = op.getdescr()
    assert isinstance(descr, TargetToken)
    if descr._ll_loop_code != 0:
        self._compute_hint_frame_locations_from_descr(descr)

