def _obfuscate_command(self, command_args: Sequence[CommandArg], obfuscate_args: Optional[Iterable[CommandArg]]=None) -> ObfuscatedCommand:
    obfuscate_args = set(chain(obfuscate_args or [], self.default_obfuscation))
    obfuscated = ' '.join((self.obfuscation if any((re.match(arg.pattern, str(command_arg)) for arg in obfuscate_args if hasattr(arg, 'pattern'))) else shlex.quote(str(command_arg)) for command_arg in command_args))
    return ObfuscatedCommand(obfuscated)

