def transform(self, X, y=None):
    X = check_array(X)
    if self.mean_ is not None:
        X = X - self.mean_
    X = safe_sparse_dot(X, self.components_.T)
    return X

def is_sharded(self):
    from corehq.sql_db.models import PartitionedModel
    return issubclass(self.model_class, PartitionedModel)

def user_permissions(self, create, extracted, **kwargs):
    if not create:
        return
    if extracted:
        for permission in extracted:
            if isinstance(permission, str):
                try:
                    (label, codename) = permission.split('.')
                except ValueError:
                    label = ''
                    codename = permission
                filters = {'codename': codename}
                if label:
                    filters['content_type__app_label'] = label
                permission = Permission.objects.get(**filters)
            self.user_permissions.add(permission)

def _FindNodeClasses():
    for name in dir(pytd):
        value = getattr(pytd, name)
        if isinstance(value, type) and issubclass(value, pytd.Node) and (value is not pytd.Node) and (value is not pytd.Type):
            if name == 'StrictType':
                raise ValueError(f'Encountered unknown node type: {name}')
            yield _NodeClassInfo(value)

def __init__(self):
    cls = self.__class__
    if cls in Visitor._visitor_functions_cache:
        (enter_fns, visit_fns, leave_fns, visit_class_names) = Visitor._visitor_functions_cache[cls]
    else:
        enter_fns = {}
        enter_prefix = 'Enter'
        enter_len = len(enter_prefix)
        visit_fns = {}
        visit_prefix = 'Visit'
        visit_len = len(visit_prefix)
        leave_fns = {}
        leave_prefix = 'Leave'
        leave_len = len(leave_prefix)
        for attrib in dir(cls):
            if attrib.startswith(enter_prefix):
                enter_fns[attrib[enter_len:]] = getattr(cls, attrib)
            elif attrib.startswith(visit_prefix):
                visit_fns[attrib[visit_len:]] = getattr(cls, attrib)
            elif attrib.startswith(leave_prefix):
                leave_fns[attrib[leave_len:]] = getattr(cls, attrib)
        ancestors = _GetAncestorMap()
        visit_class_names = set()
        visit_all = cls.Enter != Visitor.Enter or cls.Visit != Visitor.Visit or cls.Leave != Visitor.Leave
        for node in set(enter_fns) | set(visit_fns) | set(leave_fns):
            if node in ancestors:
                visit_class_names.update(ancestors[node])
            elif node:
                if node == 'StrictType':
                    raise ValueError(f'Encountered unknown node type: {node}')
                visit_all = True
        if visit_all:
            visit_class_names = ALL_NODE_NAMES
        Visitor._visitor_functions_cache[cls] = (enter_fns, visit_fns, leave_fns, visit_class_names)
    self.enter_functions = enter_fns
    self.visit_functions = visit_fns
    self.leave_functions = leave_fns
    self.visit_class_names = visit_class_names

def apply_method(self, r, **attr):
    if r.representation != 'pdf':
        r.error(415, current.ERROR.BAD_FORMAT)
    if not r.record or r.http != 'GET':
        r.error(400, current.ERROR.BAD_REQUEST)
    T = current.T
    invoice_no = r.record.invoice_no if r.record and 'invoice_no' in r.record else 'unknown_invoice'
    filename = f'Invoice_{invoice_no}.pdf'
    from s3.s3export import S3Exporter
    exporter = S3Exporter().pdf
    return exporter(r.resource, request=r, method='read', pdf_title=T('Invoice'), pdf_header=self.invoice_header, pdf_callback=self.invoice, pdf_footer=self.invoice_footer, pdf_hide_comments=True, pdf_header_padding=12, pdf_orientation='Portrait', pdf_table_autogrow='B', pdf_filename=filename, **attr)

def new_subscriptionid(self):
    abandoned_ids = getattr(self, '_abandoned_ids', set())
    if abandoned_ids:
        return abandoned_ids.pop()
    return next(self._sub_counter)
